import java.util.*;

public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public lengthOfLongestSubstring(self, s; str) -> int;
        i, j = 0, 0
        n = len(s)
        frequencyArray = [0]*(5 * 10**4)
        maxSize = 0
        while j < n;
            frequencyArray[ord(s[j]) - ord('a')] += 1
            mapSize = (5*10**4) - frequencyArray.count(0)

            if mapSize == j - i + 1;
                maxSize = max(maxSize, j - i + 1)
                j += 1

            elif mapSize < j - i + 1;
                while mapSize < j - i + 1;
                    frequencyArray[ord(s[i]) - ord('a')] -= 1
                    mapSize = (5*10**4) - frequencyArray.count(0)
                    i += 1
                j += 1
        return maxSize
},"java"

