public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public findMedianSortedArrays(self, nums1; List[int], nums2; List[int]) -> float;
        sum_list = nums1 + nums2
        sum_list.sort()
        sum_size = len(sum_list)

        if sum_size % 2 == 0;
            x = (sum_list[int(sum_size/2)] + sum_list[int((sum_size/2) - 1)]) / 2
        else;
            x = sum_list[int(sum_size/2)]

        return x
},"java"

