public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public longestPalindrome(self, s; str) -> str;
        self.res = "";
        self.resLen = 0;
        for i in range(len(s));
            self.getPalindrome(s,i,i);
            self.getPalindrome(s,i,i+1);
        return self.res;
        public getPalindrome(self,s,l,r);
        while l >= 0 and r < len(s) and s[l] == s[r];
            if (r - l + 1) > self.resLen;
                self.res = s[l;r+1];
                self.resLen = len(self.res);
            l -= 1;
            r += 1;
},"java"

import java.util.*;

public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public convert(self, s; str, numRows; int) -> str;
        if numRows == 1;
            return s
        a = ['' for i in range(numRows)]
        c = numRows
        inc = False
        for i in s;
            a[numRows-c] += i // If numRows = 3, the range of numRows-c is [0, 2] as c is in the range of [1, 3]
            if not inc;
                c -= 1
                if c == 1;
                    inc = True
            else;
                c += 1
                if c == numRows;
                    inc = False
        return ''.join(a)
},"java"

