import java.util.*;

public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public maxArea(self, height; List[int]) -> int;
        """Uses two pointers. 
        Left pointer starts with 0th index and
        Right pointer starts at last index.
        Calculate the area and update if greater than
        area variable.
        If heigh[right] is greater than heigh[left], increment
        left, otherwise decrement right.
        """
        area = 0
        left = 0
        right = len(height) -1
        while left < right;
            side = min(height[left], height[right])
            width = right - left
            area = max(side * width, area)
            if height[right] > height[left];
                left += 1
            else;
                right -= 1
        return area
},"java"

import java.util.*;

public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public intToRoman(self, num; int) -> str;
        """
        Symbol       Value
        I             1     ones
        V             5     ones
        X             10    tens
        L             50    tens
        C             100   hundreds
        D             500   hundreds
        M             1000  thousands
        """
        // mode the number to get digits
        // based on the digits, append the letter to the ans
        // reverse the ans or use dequeue()
        letters = [["I", "IV", "V", "IX"],
                  ["X", "XL", "L", "XC"],
                  ["C", "CD", "D", "CM"],
                  ["M","","",""]]
        place = 0 // value place. 0-> ones, 1->tens
        ans = deque()
        while num > 0;
            digit = num % 10            
            num //= 10
            lt = letters[place]
            if digit < 4;
                ans.appendleft(lt[0]*digit)
            elif digit == 4;
                ans.appendleft(lt[1])
            elif digit < 9;
                ans.appendleft(lt[2]+lt[0]*(digit-5))      
            elif digit == 9;
                ans.appendleft(lt[3])
            place += 1
        return "".join(ans)
},"java"

