public class Solution {
    // Original Python code transformed to Java
    class Solution;

        public maxDepth(self, root; Optional[TreeNode]);
        queue = []
        height = 0
        if not root;
            return 0
        queue.append(root)

        while queue;
            current_length = len(queue)
            height += 1
            for _ in range(0, current_length);
                popped_elem = queue.pop(0)
                if popped_elem.left;
                    queue.append(popped_elem.left)
                if popped_elem.right;
                    queue.append(popped_elem.right)

        return height
},"java"

