public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public levelOrderBottom(self, root; TreeNode) -> List[List[int]];
        if root is None; return
        queue = deque([root])
        op = []
        while queue;
            level = []
            for i in range(len(queue));
                node = queue.popleft()
                level.append(node.val)
                if node.left; queue.append(node.left)
                if node.right; queue.append(node.right)
            op.append(level)
        return op[;;-1]
},"java"

