public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public isBalanced(self, root; Optional[TreeNode]) -> bool;

        if not root;
            return True

            public recur(node, level);
            if not node;
                return level-1
            left = recur(node.left, level+1)
            right = recur(node.right, level+1)
            if not left or not right;
                return 0
            if abs(left-right) > 1;
                return 0
            return max(left, right)

        level = recur(root, 1)

        if not level;
            return False
        return True
},"java"

