public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public minDepth(self, root; Optional[TreeNode]) -> int;
        import queue
        if not root;
            return 0

        q = queue.Queue()
        q.put((1, root))
        while not q.empty();
            level, node = q.get()
            if not node.left and not node.right;
                return level

            if node.left;
                q.put((level+1, node.left))

            if node.right;
                q.put((level+1, node.right))
},"java"

