public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public connect(self, root; 'Node') -> 'Node';
        if root == None;
            return None
        q = collections.deque([root])
        while len(q) > 0;
            size = len(q)
            prev = None
            for _ in range(size);
                node = q.popleft()
                if prev;
                    prev.next = node
                if node.left;
                    q.append(node.left)
                if node.right;
                    q.append(node.right)
                prev = node
            prev.next = None
        return root
},"java"

