import java.util.*;

public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public minimumTotal(self, triangle; List[List[int]]) -> int;
        n = len(triangle)
        dp = [[-1] * n for x in range(n)]

        for j in range(n);
            dp[n-1][j] = triangle[n-1][j]
        i = n-2
        while(i>=0);
            j = i
            while(j>=0);
                down = triangle[i][j] + dp[i+1][j]
                dia = triangle[i][j] + dp[i+1][j+1]
                dp[i][j] = min(down,dia)
                j -= 1
            i -= 1
        return dp[0][0]
},"java"

