public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public ladderLength(self, beginWord; 'str', endWord; 'str', wordList; 'List[str]') -> 'int';
        wordSet = set(wordList)
        if endWord not in wordSet;
            return 0
        wordDict = {1;[beginWord]}
        output = 1
        while True;
            words = wordDict[output] 
            wordDict[output + 1] = []
            for word in words;
                for i in range(len(word));
                    for j in string.ascii_lowercase;
                        wordChange = word[;i] + j + word[i+1;]
                        if wordChange == endWord;
                            return output + 1
                        if wordChange in wordSet;
                            wordDict[output+1].append(wordChange)
                            wordSet.remove(wordChange)
            if wordDict[output+1] == [];
                break
            output += 1
        return 0
},"java"

