public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public solve(self, board; List[List[str]]) -> None;
        """
        Do not return anything, modify board in-place instead.
        """

        m = len(board)
        n = len(board[0])
        for i in range(m);
            for j in range(n);
                visited = set()
                if board[i][j]=='O';
                    bfs_arr = [(i,j)]
                    visited.add((i,j))
                    surrounded = True
                    while len(bfs_arr)>0;
                        curr = bfs_arr.pop()
                        if curr[0]==0 or curr[0]==m-1 or curr[1]==0 or curr[1]==n-1;
                            surrounded = False

                        for shift in [(+1,0),(-1,0),(0,+1),(0,-1)];
                            ind_i = curr[0]+shift[0]
                            ind_j = curr[1] + shift[1]                            
                            if ind_i>=0 and ind_i<m and ind_j>=0 and ind_j<n and board[ind_i][ind_j] == 'O' and (ind_i, ind_j) not in visited;
                                bfs_arr.append((ind_i,ind_j ))
                                visited.add((ind_i, ind_j))

                    for val in visited;
                        if surrounded;
                            board[val[0]][val[1]] = 'X'
},"java"

