public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public minCut(self, s; str) -> int;
        if len(s)<=1; return 0
        dp = []
        for x in range(-1,len(s));
            dp.append(x)
        for i in range(len(s));
            for j in range(i,len(s));
                if s[i;j]==s[j;i;-1];
                    dp[j+1]=min(dp[j+1],dp[i]+1)
        return dp[len(s)]

        public minCut1(self, s; str) -> int;
        if len(s)<=1; return 0
        self.memo=[None]*(len(s)+1)
        self.memo[0]=[[]]
        ps = self.partition(s)
        min_len=float("inf")
        for p in ps;
            min_len=min(min_len,len(p))
        return min_len - 1

        public partition(self,s);
        l = len(s)
        if self.memo[l]; return self.memo[l]
        result=[]
        for i in range(l-1,-1,-1);
            current=s[i;]
            if current==current[;;-1];
                prevs=self.partition(s[;i])
                for prev in prevs;
                    result+=[prev+[current]]
        self.memo[l]=result
        return result
},"java"

