public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public insertionSortList(self, head; ListNode) -> ListNode;

        // No need to sort for empty list or list of size 1
        if not head or not head.next;
            return head

        nodes = []
        cur = head
        while head;
            nodes.append(head)
            head = head.next

        // Sort nodes by their values ascendingly
        nodes = sorted(nodes, key=lambda node; node.val)

        // Re-organize list
        cur = head = nodes[0]
        for node in nodes[1;];
            cur.next = node
            cur = cur.next
        cur.next = None

        return head
},"java"

