public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public maxPoints(self, points; List[List[int]]) -> int;
            public solve(p1, p2);
            if p2[0] == p1[0];
                return math.inf, p1[0]
            m = (p2[1] - p1[1]) / (p2[0] - p1[0])
            b = p2[1] - m*p2[0]
            return m, b

        n = len(points)
        if n == 1;
            return 1
        lines = defaultdict(set)
        for i in range(n);
            for j in range(i+1, n);
                m, b = solve(points[i], points[j])
                lines[(m,b)].add(i)
                lines[(m,b)].add(j)

        return max([len(v) for v in lines.values()])
},"java"

