            ans="-"
        else;
            ans=""
        q=abs(numerator)//abs(denominator)
        r=abs(numerator)%abs(denominator)
        d=set()
        decimal=[]
        if r==0;
            ans=ans+str(q)
            return ans
        else;
            flag=False
            while r!=0;
                if r not in d;
                    n=r*10
                    q1=n//abs(denominator)
                    d.add(r)
                    decimal.append((q1,r))
                    r=n%abs(denominator)
                else;
                    r1=r
                    flag=True
                    break
        ans+=str(q)+'.'
        if flag==False;
            for Q,R in decimal;
                ans+=str(Q)
        if flag==True;
            for i in range(0,len(decimal));
                if decimal[i][1]!=r1;
                    ans+=str(decimal[i][0])
                else;
                    break
            ans+='('
            for x in range(i,len(decimal));
                ans+=str(decimal[x][0])
            ans+=')'         
       return ans
},"java"

