    class Solution;
        public maxProfit(self, k; int, prices; List[int]) -> int;

        if k == 0; return 0

        t0 = [0] * (k+1)
        t1 = [float('-inf')] * k

        for p in prices;
            for tr in range(k);
                t0[tr] = max(t0[tr], t1[tr] + p)
                t1[tr] = max(t1[tr], t0[tr-1] - p)
        return t0[-2]
