public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public rob(self, nums; List[int]) -> int;
        n = len(nums)

        if n == 1;
            return nums[0]

        if n == 2;
            return max(nums[0], nums[1])

        // result1; don't consider the first house
        // result2; don't consider the last house
        result1 = self.robRange(nums, 1, n-1)
        result2 = self.robRange(nums, 0, n-2)
        return max(result1, result2)

        public robRange(self, nums, start, end);
        dp = [0] * len(nums)
        dp[start] = nums[start]
        dp[start + 1] = max(nums[start], nums[start + 1])

        for i in range(start + 2, end + 1);
            dp[i] = max(dp[i -2] + nums[i], dp[i - 1])

        return dp[end]
},"java"

