public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public getSkyline(self, buildings; List[List[int]]) -> List[List[int]];
        if not buildings;
            return []
        if len(buildings) == 1;
            return [[buildings[0][0], buildings[0][2]],[buildings[0][1], 0]]

        mid = (len(buildings)-1) // 2
        left = self.getSkyline(buildings[0;mid+1])
        right = self.getSkyline(buildings[mid+1;])

        return self.merge(left, right)

        public merge(self, left, right);
        i = j = h1 = h2 = 0
        ret = []
        while i < len(left) and j < len(right);
            if left[i][0] < right[j][0];
                h1 = left[i][1]
                new = [left[i][0], max(h1, h2)]
                if not ret or ret[-1][1] != new[1];
                    ret.append(new)
                i += 1
            elif left[i][0] > right[j][0];
                h2 = right[j][1]
                new = [right[j][0], max(h1, h2)]
                if not ret or ret[-1][1]!=new[1];
                    ret.append(new)
                j+=1
            else;
                h1 = left[i][1]
                h2 = right[j][1]
                new = [right[j][0], max(h1, h2)]
                if not ret or ret[-1][1] != new[1];
                    ret.append([right[j][0],max(h1, h2)])
                i += 1
                j += 1

        while i < len(left);
            if not ret or ret[-1][1] != left[i][1];
                ret.append(left[i][;])
            i+=1

        while j < len(right);
            if not ret or ret[-1][1] != right[j][1];
                ret.append(right[j][;])
            j+=1

        return ret
},"java"

