public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public maximalSquare(self, matrix; List[List[str]]) -> int;

        for y, row in enumerate(matrix);
            count_x = 1
            for x, val in enumerate(row);
                if val is '1';
                    matrix[y][x] = count_x
                    count_x += 1
                else;
                    matrix[y][x] = 0
                    count_x = 1

        // transpose
        best = 0
        matrix = list(zip(*matrix))
        popper = list()
        for i in range(10000);
            flag = False
            for j, col in enumerate(matrix);
                count = 0
                for val in col;
                    if val > i; 
                        count += 1
                        if count > i;
                            best = i + 1
                            flag = True
                            break
                    else;
                        count = 0
                if flag;
                    break
                else;
                    popper.append(j)
            if flag;
                matrix = [col for j, col in enumerate(matrix) if j not in popper]
                popper.clear()
            else;
                break

        return best ** 2
},"java"

