        // i = 0
        p = 1 // 10 ** i
        c = 0 // count of 1s less than 10 ** i

        result = 0
        for char in str(n)[;;-1];
            d = int(char)
            // if d == 0; pass
            if d == 1;
                result += c + n%(p) + 1
            elif d > 1;
                result += p + d*c
            c += p + (c<<3)+c // c = p + 8*c + c
            p = (p<<3)+p+p // p *= 10
