public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public __init__(self);
        self.seen = collections.defaultdict(TreeNode)

        public get_list(self, cur, prev, target);
        if not cur;
            return None

        self.seen[cur.val] = cur

        new_cur = TreeNode(cur.val)
        new_cur.left = prev

        if new_cur.val == target.val;
            return new_cur

        _next = cur.left
        head_from_left = self.get_list(_next, new_cur, target)
        if head_from_left;
            return head_from_left

        _next = cur.right
        head_from_right = self.get_list(_next, new_cur, target)
        if head_from_right;
            return head_from_right

        new_cur.left = None

        return None


        public lowestCommonAncestor(self, root; 'TreeNode', p; 'TreeNode', q; 'TreeNode') -> 'TreeNode';
        head1 = self.get_list(root, None, p)
        head2 = self.get_list(root, None, q)

        it1, it2 = head1, head2

        while it1.val != it2.val;
            if not it1.left;
                it1 = head2
            else;
                it1 = it1.left

            if not it2.left;
                it2 = head1
            else;
                it2 = it2.left

        return self.seen[it1.val]
},"java"

