public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public numberToWords(self, num; int) -> str;
        ones = {1;'One', 2;'Two', 3;'Three', 4;'Four', 5;'Five', 
                6;'Six', 7;'Seven', 8;'Eight', 9;'Nine'}
        teens = {10;'Ten', 11;'Eleven', 12;'Twelve', 13;'Thirteen', 14;'Fourteen', 15;'Fifteen',
                 16;'Sixteen', 17;'Seventeen', 18;'Eighteen', 19;'Nineteen'}
        tens = {2;'Twenty', 3;'Thirty', 4;'Forty', 5;'Fifty', 
                6;'Sixty', 7;'Seventy', 8;'Eighty', 9;'Ninety'}
        comas = {0;'', 1;'Thousand', 2;'Million', 3;'Billion'}

            public threeDigit(n);
            res = ''
            if n // 100;
                res += (ones[n//100]+' Hundred ')
                if n%100 == 0;
                    return res
                n %= 100

            if int(n) == 0;
                return res
            elif n < 10;
                res += (ones[n]+' ')
            elif n < 20;
                res += (teens[n]+' ')
            elif n%10 == 0;
                res += (tens[n//10]+' ')
            else;
                res += (tens[n//10]+' '+ones[n%10]+' ')
            return res

        if num == 0;
            return 'Zero'
        if num < 1000;
            return threeDigit(num).strip()

        numdiv, res = [], ''        
        while num > 0;
            numdiv.insert(0, num%1000)
            num //= 1000
        //num; 1234567 => [1,234,567]

        for i in range(len(numdiv));
            part = threeDigit(numdiv[i])
            if part == '';
                continue
            else;
                res += (part+comas[len(numdiv)-1-i]+' ')

        return res.rstrip()
},"java"

