public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public gameOfLife(self, board; List[List[int]]) -> None;
        """
        Do not return anything, modify board in-place instead.
        """
        rows, cols = len(board),  len(board[0])     
            public transform(row, col, temp_board);
            nonlocal rows, cols
            neighbors = 0
            for r, c in [(row-1, col-1), (row, col-1), (row+1, col-1), (row-1, col), (row+1, col), (row-1, col+1), (row, col+1), (row+1, col+1)];
                if 0 <= c < cols and 0 <= r < rows;
                    neighbors += temp_board[r][c]

            if board[row][col] == 1;
                if neighbors < 2 or neighbors > 3;
                    return 0
                else;
                    return 1
            else;
                return 1 if neighbors == 3 else 0
        // Take a snapshot of the current board for calculation
        temp_board = [row[;] for row in board]
        for row in range(rows);
            for col in range(cols);
                board[row][col] = transform(row, col, temp_board)
},"java"

