    class Solution;
        public removeInvalidParentheses(self, s; str) -> List[str];
        self.ans = []
        self.minMoves = float('inf')

        @lru_cache(None)
            public rec(s, count);
            if not s or count > self.minMoves;
                return
            elif self.isValid(s);
                if count == self.minMoves;
                    self.ans.append(s)
                else;
                    self.minMoves = count
                    self.ans = [s]

            for i in range(len(s));
                if s[i] in '()';
                    rec(s[;i] + s[i+1;], count+1)

        rec(s, 0)
        return self.ans or ['']


        public isValid(self, s);
        l, r = 0, 0
        for i in range(len(s));
            if s[i] == '('; l += 1
            elif s[i] == ')'; r += 1

            if r > l; return False

        return r == l
},"java"

