public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public findMinHeightTrees(self, n; int, edges; List[List[int]]) -> List[int];

        if n<2;
            return range(n)

        graph=defaultdict(set)
        indegree=[0]*n
        for u,v in edges;
            graph[u].add(v)
            graph[v].add(u)
            indegree[u]+=1
            indegree[v]+=1

        queue=[]
        for i in range(n);
            if indegree[i]==1;
                queue.append(i)

        count=n

        while count>2;
            new_queue=[]

            for current in queue;

                for neighbour in graph[current];
                    indegree[neighbour]-=1
                    graph[neighbour].remove(current)
                    if indegree[neighbour]==1;
                        new_queue.append(neighbour)

                count-=1
            queue=new_queue

        return queue
},"java"

