public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public coinChange(self, coins; List[int], amount; int) -> int;
        // min number of coins summing up to current amount i
        memo = [-666]*(amount + 1)
        return self.dp(coins, amount, memo)

        public dp(self, coins, amount, memo);
        if (amount == 0); return 0
        if (amount < 0); return -1

        if (memo[amount] != -666);
            return memo[amount]

        res = sys.maxsize
        for coin in coins;
            subProblem = self.dp(coins, amount - coin, memo)
            if (subProblem == -1);
                continue
            res = min(subProblem + 1, res)

        memo[amount] = res if res != sys.maxsize else -1
        return memo[amount]
},"java"

