public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public findItinerary(self, tickets; List[List[str]]) -> List[str];
        edges = collections.defaultdict(list)
        n = len(tickets)

        for i in range(len(tickets));
            edges[tickets[i][0]].append(tickets[i][1])
        for k in edges;
            edges[k].sort()

        itinerary_list = ['JFK']
        self.traverse(edges, itinerary_list, n)
        return itinerary_list


        public traverse(self, edges, itinerary_list, n);
        if len(itinerary_list) == n+1;
            return True
        cur_node = itinerary_list[-1]

        for i in range(len(edges[cur_node]));
            if edges[cur_node][i] != '//';
                temp = edges[cur_node][i]
                itinerary_list.append(temp)
                edges[cur_node][i] = '//'
                if self.traverse(edges, itinerary_list, n);
                    return True
                edges[cur_node][i] = temp
                itinerary_list.pop()
        return False
},"java"

