public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public reverseVowels(self, s; str) -> str;
        s = list(s)
        vowel = list('AEIOU')
        left_counter, right_counter = 0, len(s) - 1
        l_val, r_val = None, None
        while left_counter<right_counter;
            if s[left_counter].upper() in vowel;
                l_val = left_counter
            elif l_val is None;
                left_counter += 1
            if s[right_counter].upper() in vowel;
                r_val = right_counter
            elif r_val is None;
                right_counter -= 1
            if l_val is not None and r_val is not None;
                s[l_val], s[r_val] = s[r_val], s[l_val]
                l_val = r_val = None
                left_counter +=1
                right_counter -=1
            if left_counter > right_counter;
                break
        return "".join(s)
},"java"

