public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public topKFrequent(self, nums; List[int], k; int) -> List[int];

        nTof = {}

        for i in nums;
            if nTof.get(i) is None;
                nTof[i] = 1
            else;
                nTof[i] += 1

        unique = list(nTof.keys())

            public partition(unique, l, r);
            pivot, p = nTof[unique[r]], r

            i = l
            while i < p;
                if nTof[unique[i]] > pivot;
                    unique[i], unique[p-1] = unique[p-1], unique[i]
                    unique[p], unique[p-1] = unique[p-1], unique[p]
                    i -= 1
                    p -= 1
                i += 1
            return p

            public quickSelect(unique, l, r, k);
            p = partition(unique, l, r)

            if p > k;
                quickSelect(unique, l, p-1, k)
            if p < k;
                quickSelect(unique, p+1, r, k)

            return unique[k;]

        return quickSelect(unique, 0, len(unique)-1, len(unique)-k)
},"java"

