    class Solution;
        public deserialize(self, s; str) -> NestedInteger;
        stack = []
        integerStr = ''

        for c in s;
            if c == '[';
                stack.append(NestedInteger())
            elif c == ']';
                if len(integerStr)>0;
                    stack[-1].add(NestedInteger(int(integerStr)))
                integerStr = ''
                poppedList = stack.pop()
                if len(stack)==0;
                    return poppedList
                stack[-1].add(poppedList)
            elif c == ',';
                if len(integerStr)>0;
