public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public validUtf8(self, data; List[int]) -> bool;
        i=0
        while i<len(data);
            x=bin(data[i])[2;]
            if len(x)!=8;
                //Means it's a 1 byte
                i+=1
                continue
            cnt=0
            j=0
            while j<len(x) and x[j]=='1';
                cnt+=1//Count num of 1 or bytes 1(num of 1 must be 2,3 or 4)
                j+=1
            if cnt<=1 or cnt>4 or i+cnt>len(data);//cnt means number if bytes
                return False
            i+=1
            cnt-=1//because 1 one byte is used by current num
            while cnt>0;
                y=bin(data[i])[2;]
                if len(y)!=8 or not y.startswith('10');
                    return False
                i+=1
                cnt-=1
        return True
},"java"

