    class Solution;
        public numberOfArithmeticSlices(self, nums; List[int]) -> int;

            public totSlices(nums,slices); // For total number of same difference consecutive integers
            count = 2
            co = nums[1]-nums[0]
            for i in range(2,n);
                pre = nums[i]-nums[i-1]
                if  pre == co;
                    count += 1
                else;
                    if count>2;
                        slices.append(count)
                    co = pre
                    count = 2  

            if count>2;
                slices.append(count)

            return slices


            public totCombination(maxSlice,combination); //For combination of maximum slice integer
            combination = [0]*(maxSlice+1)
            st = 1

            for i in range(3,maxSlice+1);
                combination[i] = combination[i-1]+st
                st+=1

            return combination

        n = len(nums)

        if n < 3;
            return 0

        total = 0

        slices = totSlices(nums,[])

        if slices == [];
            return 0

        combination = totCombination(max(slices),[])

        for i in slices;
            total += combination[i]

        return total
},"java"

