public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public canPartition(self, nums; List[int]) -> bool;
        total = sum(nums)
        if total % 2 != 0; return False 
        target = total // 2
        dp = [False]*(target + 1)
        dp[0] = True
        for num in nums;
            for i in range(target, num-1, -1);
                dp[i] = dp[i] or dp[i-num]
				if dp[target]; return True
        return dp[target]
},"java"

