public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public countBattleships(self, board; List[List[str]]) -> int;
        if not board;
            return 0
        counter = 0
        for i in range(len(board));
            for j in range(len(board[0]));
                if board[i][j] == "X";
                    self.dfs(board, i, j)
                    counter += 1
        return counter

        public dfs(self, board, i, j);
        if i < 0 or j < 0 or i >= len(board) or j >= len(board[i]) or board[i][j] != "X";
            return
        board[i][j] = "//"
        self.dfs(board, i+1, j)
        self.dfs(board, i-1, j)
        self.dfs(board, i, j+1)
        self.dfs(board, i, j-1)
},"java"

