    class Solution;
        public flatten(self, head; 'Node') -> 'Node';
        if head is None;
            return None

        return self.dfs(head)

        public dfs(self, node);
        original_next = node.next
        tail = node

        if node.child;
            node.next = self.dfs(node.child)
            node.next.prev = node
            node.child = None
            tail = node.next
            while tail.next;
                tail = tail.next

        if original_next;
            tail.next = self.dfs(original_next)
            tail.next.prev = tail

        return node
},"java"

