public class Solution {
    // Original Python code transformed to Java
    class Solution;    
        public deleteNode(self, root; Optional[TreeNode], key; int) -> Optional[TreeNode];
        if not root;
            return None

        if root.val == key;
            // first case - no childrens
            if not root.left and not root.right;
                return None

            // second case - there is one of chlidren (left or right)
            if not root.left;
                return root.right

            if not root.right;
                return root.left

            // third case - there are both childrens (left and right)
            tmp = root.left
            while tmp.right;
                tmp = tmp.right

            root.val = tmp.val
            root.left = self.deleteNode(root.left, root.val)

        if root.val > key;
            root.left = self.deleteNode(root.left, key)
        else;
            root.right = self.deleteNode(root.right, key)

        return root
},"java"

