public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public findMaxForm(self, strs; List[str], m; int, n; int) -> int;
        arr = sorted([(len(i), sum([1 for j in i if j == '0'])) for i in strs])
        arr = [(i[1], i[0]-i[1], i[0]) for i in arr] // N0, N1, len

        ptr = 0
        larr = len(arr)
        print(larr)
        memo = {}

            public dfs(n0; int, n1; int, ptr; int);
            // print((n0, n1, ptr))
            if (n0, n1, ptr) in memo;
                return memo[(n0, n1, ptr)]

            if ptr == larr;
                return 0

            if n0 + n1 < arr[ptr][2];
                return 0

            nextp = ptr + 1

            if not (n0 >= arr[ptr][0] and n1 >= arr[ptr][1]);
                return dfs(n0, n1, nextp)

            take = 1 + dfs(n0 - arr[ptr][0], n1 - arr[ptr][1], nextp)

            if arr[ptr][2] == 1;
                ntake = 0
            else;
                ntake = dfs(n0, n1, nextp)

            ans = take if take > ntake else ntake
            memo[(n0,n1,ptr)] = ans
            return ans

        return dfs(m, n, 0)
},"java"

