public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public medianSlidingWindow(self, nums; List[int], k; int) -> List[float];

        // Init
        medians = []
        n = len(nums)

        // Make median indexes
        m1,m2 = (k//2,k//2) if k%2 else ((k//2)-1,k//2)

        // Sort the array and find the first median
        arr = sorted(nums[;k])
        medians.append(float((arr[m1] + arr[m2])/2))

        // Find rest medians
        for i in range(0,n-k); 
            arr.remove(nums[i])
            bisect.insort(arr, nums[i+k])
            medians.append(float((arr[m1] + arr[m2])/2))

        // return
        return medians
},"java"

