public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public findMaximizedCapital(self, k; int, w; int, profits; List[int], capital; List[int]) -> int;
        projects = sorted([(c, p) for p, c in zip(profits, capital)])
        i, N = 0, len(projects)
        profits_maxheap = []
        cur_capital = w
        while k > 0;
            while i < N and cur_capital >= projects[i][0];
                heapq.heappush(profits_maxheap, -projects[i][1])
                i += 1
            if not profits_maxheap;
                break
            cur_capital -= heapq.heappop(profits_maxheap)
            k -= 1
        return cur_capital
},"java"

