            return 0

        _sum = self.traversal(node.left, d, max_freq) + self.traversal(node.right, d, max_freq) + node.val

        d[_sum] = d.get(_sum, 0) + 1

        max_freq[0] = max(max_freq[0], d[_sum])

        return _sum


