public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public longestPalindromeSubseq(self, s; str) -> int;
        memo = {}

            public helper(s; str, i; int, j;int, memo; dict);
            if (i,j) in memo;
                return memo[(i,j)]

            if i==j;
                memo[(i,j)] = 1
                return 1

            if i>j;
                memo[(i,j)] = 0
                return 0

            if s[i] == s[j];
                sub = helper(s, i+1, j-1, memo)
                memo[(i+1,j-1)] = sub
                return sub + 2

            left = helper(s, i, j-1, memo)
            memo[(i,j-1)] = left
            right = helper(s, i+1, j, memo)
            memo[(i+1,j)] = right
            return max(left, right)

        return helper(s, 0, len(s)-1, memo)
},"java"

