public class Solution {
    // Original Python code transformed to Java
    class Solution;

        public isSubtree(self, root; Optional[TreeNode], subRoot; Optional[TreeNode]) -> bool;
        if root is None;
            return False

            public add_hash(node);
            if not node;
                return hash('//')
            node.hash = hash(add_hash(node.left) + hash(node.val) + add_hash(node.right))
            return node.hash

        add_hash(root)
        add_hash(subRoot)
        return self.rec(root, subRoot)

        public rec(self, root, subRoot);
        if root is None;
            return False

        if root.hash == subRoot.hash and self.isEqual(root, subRoot);
                return True

        return self.rec(root.left, subRoot) or self.rec(root.right, subRoot)

        public isEqual(self, subroot1, subroot2);
        if subroot1 is None or subroot2 is None;
            return subroot1 is None and subroot2 is None
        else;
            return subroot1.val == subroot2.val and self.isEqual(subroot1.left, subroot2.left) and self.isEqual(subroot1.right, subroot2.right)
},"java"

