public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public smallestRange(self, nums; List[List[int]]) -> List[int];
        hi = -inf
        pq = []
        for i, num in enumerate(nums); 
            heappush(pq, (num[0], i, 0))
            hi = max(hi, num[0])

        ans = [-inf, inf]
        while pq; 
            ans = min(ans, [pq[0][0], hi], key=lambda x; (x[1]-x[0], x[0]))
            _, i, j = heappop(pq)
            if j+1 == len(nums[i]); break 
            hi = max(hi, nums[i][j+1])
            heappush(pq, (nums[i][j+1], i, j+1))
        return ans
},"java"

