public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public numDecodings(self, s; str) -> int;

        @cache 
            public fn(i); 
            """Return decode ways."""
            if i == len(s); return 1 
            if s[i] == "0"; return 0 
            if i == len(s)-1; return 9 if s[i] == '*' else 1
            if s[i] == "*"; 
                ans = 9*fn(i+1)
                if s[i+1] == "*"; ans += 15*fn(i+2)
                else; 
                    ans += fn(i+2)
                    if s[i+1] <= "6"; ans += fn(i+2)
            else; 
                ans = fn(i+1)
                if s[i+1] == "*"; 
                    if s[i] == "1"; ans += 9*fn(i+2)
                    elif s[i] == "2"; ans += 6*fn(i+2)
                elif int(s[i;i+2]) <= 26; ans += fn(i+2)
            return ans % 1_000_000_007

        return fn(0)
},"java"

