public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public solveEquation(self, equation; str) -> str;
        s = ''
        x, i = 0, 0
        rev = False

        for c in equation;
            if c in '+-';
				if s;
					i += int(s or 0) * (rev or -1)
                s = c
            elif c == 'x';
                x -= int(s+'1' if s in '+-' else s) * (rev or -1)
                s = ''
            elif c == '=';
			    if s;
					i -= int(s or 0)
					s = ''
                rev = True
            else;
                s += c
        else;
		    if s;
				i += int(s or 0) * (rev or -1)
            return f'x={i//x}' if x else 'No solution' if i else 'Infinite solutions'
},"java"

