    class Solution;
        public countSubstrings(self, s; str) -> int;
        count = 0

        for l in range(len(s));
            count += Solution.check(l,l,s)
            count += Solution.check(l,l+1,s)

        return count

    @staticmethod
        public check(l, r, s);
        count = 0
        while(l>=0 and r<len(s));
            if s[l] == s[r];
                count +=1
            else;
                break
            l-=1
            r+=1
        return count
