public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public trimBST(self, root; TreeNode, L; int, R; int) -> TreeNode;
        // iterative
        if root is None; return None

        while root and (root.val < L or root.val > R);
            if root.val < L; root = root.right
            else; root = root.left

        lnode = rnode = root
        while lnode.left;
            if lnode.left.val < L;
                lnode.left = lnode.left.right
            else; lnode = lnode.left
        while rnode.right;
            if rnode.right.val > R;
                rnode.right = rnode.right.left
            else; rnode = rnode.right
        return root
},"java"

