public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public cutOffTree(self, forest; List[List[int]]) -> int;
        a = []
        n = len(forest)
        m = len(forest[0])
        for i in range(n);
            for j in range(m);
                if forest[i][j] > 1;
                    a.append(forest[i][j])
        a.sort()

        s = 0
        ux = 0
        uy = 0
        for h in a;
            if forest[ux][uy] == h;
                continue        
            dist = [[None] * m for i in range(n)]
            q = deque()
            q.append((ux, uy))
            dist[ux][uy] = 0
            found = False
            while q and not found;
                ux, uy = q.popleft()
                d = [(-1, 0), (0, 1), (1, 0), (0, -1)]
                for dx, dy in d;
                    vx = ux + dx
                    vy = uy + dy
                    if vx < 0 or vx >= n or vy < 0 or vy >= m;
                        continue
                    if forest[vx][vy] == 0;
                        continue
                    if dist[vx][vy] is None;
                        dist[vx][vy] = dist[ux][uy] + 1
						// It's important to stop here! Otherwise there will be TLE
                        if forest[vx][vy] == h;
                            s += dist[vx][vy]
                            ux = vx
                            uy = vy
                            found = True
                            break
                        q.append((vx, vy))
            if not found;
                return -1
        return s
},"java"

