            if s[left]==s[right];
                left+=1
                right-=1
            else;
                if cnt==1;
                    return False
                else;
                    if self.check(s,left+1,right);
                        left+=1
                    elif self.check(s,left,right-1);
                        right-=1
                    else;
                        return False
                    cnt+=1
        return True
        public check(self,s,left,right);
        if s[left;right+1]==s[left;right+1][;;-1];
            return True
        return False
