public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public __init__(self);
        self.possibleMoves = [(-2,1),(-1,2),(1,2),(2,1),(2,-1),(1,-2),(-1,-2),(-2,-1)]
        self.mem = dict()

        public isInside(self, r, c, N);
        if r < 0 or c < 0 or r >= N or c >= N;
            return False
        return True

        public Util(self, N, K, r, c);
        if K == 0;
            return 1
        if (K, r, c) in self.mem;
            return self.mem[(K, r, c)]
        total = 0
        for i, j in self.possibleMoves;
            if self.isInside(r + i, c + j, N);
                corMoves = self.Util(N, K - 1, r + i, c + j)
                total += corMoves
        self.mem[(K, r, c)] = total
        return total

        public knightProbability(self, N; int, K; int, r; int, c; int) -> float;
        totalPossible = self.Util(N, K, r, c)
        return totalPossible / 8 ** K
},"java"

