public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public minimumDeleteSum(self, s1; str, s2; str) -> int;
        @lru_cache(None)
            public getASCII(char);
            return ord(char)

        if len(s1) < len(s2);
            s1, s2 = s2, s1

        m, n = len(s1), len(s2)

        dp = [0]*(n+1)

        for i in range(1, n+1);
            dp[i] += dp[i-1] + getASCII(s2[i-1])

        for i in range(1, m+1);
            new_dp = [0]*(n+1) 
            new_dp[0] = dp[0] + getASCII(s1[i-1])

            for j in range(1, n+1);
                if s1[i-1] == s2[j-1];
                    new_dp[j] = dp[j-1]
                else;
                    new_dp[j] = min(getASCII(s1[i-1])+dp[j], getASCII(s2[j-1])+new_dp[j-1])

            dp = new_dp

        return dp[-1]
},"java"

