public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public numSubarrayProductLessThanK(self, nums; List[int], k; int) -> int;

        // Init
        n = len(nums)
        m = 0 // no. of subarrays

        // Base Case
        if k == 0;
            return 0

        // Base Case
        if sum(nums) == n;
            return (n)*(n+1)//2 if k > 1 else 0 

        // For each element
        for i,num_i in enumerate(nums);

            // Calc curr product
            curr_prod = num_i

            // Check if is less then k, else continue
            if curr_prod < k;
                m += 1
            else;
                continue

            // For each j from i+1 to n-1
            for num_j in nums[i+1;];

                // calc current product
                curr_prod = curr_prod * num_j

                // Check if is less then k, else break
                if curr_prod < k;
                    m += 1
                else;
                    break

        return m
},"java"

