    // Binary Search Tree Solution -> If exact matching of intervals found then return False
//                                Else you can add this interval to that particular node's left or right
class Node;
        public __init__(self, s, e);
        self.s = s
        self.e = e
        self.left = None
        self.right = None
class MyCalendar;
        public __init__(self);
        self.head = None

        public insert(self, s, e, node);
        if s >= node.e;
            if node.right; return self.insert(s, e, node.right)
            else; 
                nn = Node(s, e)
                node.right = nn
                return True
        elif e <= node.s;
            if node.left; return self.insert(s, e, node.left)
            else;
                nn = Node(s, e)
                node.left = nn
                return True
        else; return False

        public book(self, s; int, e; int) -> bool;
        if self.head == None;
            nn = Node(s, e)
            self.head = nn
            return True
        return self.insert(s, e, self.head)
},"java"

