        color_to_change = image[sr][sc]

            public dfs(r,c);
            if(r<0 or c<0 or r>rows-1 or c>cols-1 or image[r][c] == newColor or image[r][c]!=color_to_change);
                return
            image[r][c] = newColor

            //iterate through all four directions
            dfs(r+1,c)
            dfs(r-1,c)
            dfs(r,c+1)
            dfs(r,c-1)

        dfs(sr,sc)
        return image
