public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public networkDelayTime(self, times; List[List[int]], n; int, k; int) -> int;
        d = {}
        graph = [[] for _ in range(n)]
        for i in times;
            d[(i[0]-1,i[1]-1)] = i[2]
            graph[i[0]-1].append(i[1]-1)        
        parent = [-1]*n
        cost = [10**9]*n
        visited = [False]*n
        cost[k-1] = 0
        x = 0
        while x <= n-1;
            m = (-1,10**9)
            for i in range(n);
                if not visited[i] and m[1] > cost[i];
                    m = (i,cost[i])
            for i,j in enumerate(graph[m[0]]);
                if (m[0],j) in d and cost[j] > cost[m[0]] + d[(m[0],j)];
                    cost[j] = cost[m[0]] + d[(m[0],j)]
                    parent[j] = m[0]
            visited[m[0]] = True
            x += 1
        return -1 if (max(cost)) == 10**9 else max(cost)
},"java"

