public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public orderOfLargestPlusSign(self, n; int, mines; List[List[int]]) -> int;
        dp = [[n] * n for _ in range(n)]
        for i, j in mines;
            dp[i][j] = 0

        for i in range(n);
            left = up = right = down = 0
            for j in range(n);
                if dp[i][j] == 0;
                    left = 0
                else;
                    left += 1
                    dp[i][j] = min(dp[i][j], left)

                if dp[j][i] == 0;
                    up = 0
                else;
                    up += 1
                    dp[j][i] = min(dp[j][i], up)

                j = ~j
                if dp[i][j] == 0;
                    right = 0
                else;
                    right += 1
                    dp[i][j] = min(dp[i][j], right)

                if dp[j][i] == 0;
                    down = 0
                else;
                    down += 1
                    dp[j][i] = min(dp[j][i], down)

        return max(val for row in dp for val in row)
},"java"

