public class Solution {
    // Original Python code transformed to Java
    class Solution;
        public maxProfitAssignment(self, difficulty; List[int], profit; List[int], worker; List[int]) -> int;
        d = defaultdict(int)
        for k,v in zip(difficulty,profit);
            d[k] = max(d[k],v)
        bucket = [0 for _ in range(max(worker)+1)]
        val = 0
        for i in range(len(bucket));
            if i in d;
                val = max(val,d[i])
            bucket[i] = val
        return sum([bucket[w] for w in worker])
},"java"

