    def combinationSum3(self, k: int, n: int) -> List[List[int]]:

        res = []

        self.backtrack(k, n, [],0,1, res)

        return res

    def backtrack(self, k, n, cur, comb, ind, res):

        if comb > n:
            return 
        elif comb == n and len(cur) == k:
            res.append([]+cur)
        else:

            for i in range(ind,10):
                cur.append(i)

                self.backtrack(k, n, cur, comb+i, i+1, res)
                cur.pop()
