        arr = sorted(nums[:k])
        medians.append(float((arr[m1] + arr[m2])/2))

        # Find rest medians
        for i in range(0,n-k): 
            arr.remove(nums[i])
            bisect.insort(arr, nums[i+k])
            medians.append(float((arr[m1] + arr[m2])/2))

        # return
        return medians
