    def findRedundantConnection(self, edges: List[List[int]]) -> List[int]:
        dict={}
        n=len(edges)
        for i in range(1,n+1):
            dict[i]=i

        def find_parent(u):
            if dict[u]==u:

                return u
            else:
                a=find_parent(dict[u])

                dict[u]=a
                return a

        for i,j in edges:
            u=find_parent(i)
            v=find_parent(j)

            if u==v:
                return [i,j]
            else:
                dict[v]=u
