// class Solution:

    def __init__(self, n: int, blacklist: List[int]):
        # The size of whitelist
        self.white_len = n - len(blacklist)
        # Last index of the array
        self.last_idx = n - 1
        # Mapping dictionary
        self.mapping = {}
        # Set the index of blacklist element all to -1
        for i in blacklist:
            self.mapping[i] = -1

        for i in blacklist:
            # skip blacklist
            if i >= self.white_len:
                continue
            while self.last_idx in blacklist:
                self.last_idx -= 1
            self.mapping[i] = self.last_idx
            self.last_idx -= 1

    def pick(self) -> int:
        idx = randint(0,self.white_len-1)
        if idx in self.mapping:
            return self.mapping[idx]
        return idx
