// class Solution:
    def findLength(self, nums1: List[int], nums2: List[int]) -> int:
        def helper(l):
            base = 1 << 7
            M = 10 **9 + 7
            a = pow(base, l, M)
            t1, t2 = 0, 0
            hashes = set()
            for i in range(len(nums1)):
                t1 = (base * t1 + nums1[i]) % M
                if i >= l:
                    t1 -= a * nums1[i - l]
                    t1 %= M
                if i >= l - 1:
                    hashes.add(t1)

            for j in range(len(nums2)):
                t2 = (base * t2 + nums2[j]) % M
                if j >= l:
                    t2 -= a * nums2[j - l]
                    t2 %= M
                if j >= l - 1:
                    if t2 in hashes: return True
            return False

        a, b = 0, min(len(nums1), len(nums2))
        while a < b:
            m = (a + b + 1) // 2
            if helper(m):
                a = m
            else:
                b = m - 1
        return a
