    def countPrimes(self, n: int) -> int:
        if n < 3:
            return 0

        primes = [1]*n
        primes[0] = primes[1] = 0
        for i in range(2,int(n**0.5)+1):
            if primes[i] != 0:
                for j in range(2*i,n,i):
