// class Solution:
    def canCross(self, s: List[int]):
		# memory variable
        mem = dict()

		# k = jump variable; i = current index; s = stones list; mem = memory dictionary
        def frog(s, k, i, mem):
			# unique key
            key = str(s[i]) + ":" + str(k) + ":" + str(i)

            if i == len(s)-1:
                return True
            if key in mem:
                return mem[key]
			# possible jumps
            jumps = [k-1, k, k+1]

            result = False

            for jump in jumps:
                if jump and s[i]+jump in s:
                    result = frog(s,jump,s.index(s[i]+jump,i),mem)
                mem[key] = result 

            return mem[key]

        frog(s, 0, 0, mem)

        return True in mem.values()

