// class Solution:
    def leastBricks(self, wall: List[List[int]]) -> int:
        edge = []
        for w in wall: 
            prefix = 0
            for k in range(len(w)-1): 
                prefix += w[k]
                edge.append(prefix)

        ans = cnt = 0
        prev = None
        for x in sorted(edge): 
            cnt = 1 if x != prev else cnt+1 # reset counter 
            ans = max(ans, cnt)
            prev = x
        return len(wall) - ans

