// class Solution:
    def maxDepth(self, root: 'Node') -> int:

        def dfs(root: 'Node', length: int):
            if root is None:
                return

            length += 1

            if not root.children:
                result.append(length)
            else:
                for child in root.children:
                    dfs(child, length)

        result = []
        dfs(root, length=0)

        if not result:
            return 0

        return max(result)

