    def findTilt(self, root: TreeNode) -> int:
        cur_sum = [0]
        def helper(node: TreeNode):
            if not node: return 0
            lt = helper(node.left)
            rt = helper(node.right)
            cur_sum[0] += abs(lt-rt)
            return node.val + lt + rt
        helper(root)
        return cur_sum[0]

