    def checkInclusion(self, s1: str, s2: str) -> bool:
        d1={}
        d2={}
        if(len(s1)>len(s2)):
            return False
        sl = len(s1)
        left = 0
        right = sl-1

        for i in s1:
            if(i not in d1):
                d1[i] = 1
            else:
                d1[i] +=1

        for i in range(left,right+1):
            if(s2[i] not in d2):
                d2[s2[i]] = 1
            else:
                d2[s2[i]] +=1

        if(d1 == d2):
            return True

        while(right < len(s2)-1):
            right+=1
            if(s2[right] not in d2):
                d2[s2[right]] = 1
            else:
                d2[s2[right]] +=1

            if(d2[s2[left]] == 1):
                del d2[s2[left]]
            else:
                d2[s2[left]]-=1
            left+=1
            if(d1 == d2):
                return True


        return False

