    def fractionAddition(self, expression: str) -> str:
        n, d = 0, 1
        nums = (int(x) for x in re.findall("[+-]?\d+", expression))
        for nn, dd in zip(*[iter(nums)]*2):
            n = n*dd + nn*d
            d *= dd
        g = gcd(n, d)
        return f"{n//g}/{d//g}"

