    def findLHS(self, nums: List[int]) -> int:

        c = Counter(nums)
        res = 0
        for x in set(nums):

            less, big = x - 1, x + 1
            if less in c or big in c:
                res = max(res, c[less] + c[x], c[big] + c[x])
        return res

