// class Solution:
    def averageOfLevels(self, root: Optional[TreeNode]) -> List[float]:
        lst=[root]
        flst=[]
        avg=[]
        sm,ct=0,0
        while lst:
            x=lst.pop(0)
            sm+=x.val
            ct+=1
            if x.left:
                flst.append(x.left)
            if x.right:
                flst.append(x.right)
            if lst==[]:
                lst=flst[:]
                flst=[]
                av=sm/ct
                avg.append(round(av,5))
                sm=0
                ct=0
        return avg

