    def replaceWords(self, dictionary: List[str], sentence: str) -> str:
        s = sentence.split()
        dictionary.sort(key=lambda x:len(x))
        for i,j in enumerate(s):
            for v in dictionary:
                if j.startswith(v):
                    s[i] = v
                    break
        return ' '.join(s)

