// Original Python code transformed to Rust
// class Solution:
    def valid(self, s, stack=[]):
        i, l = 0, len(s)
        if not l:
            return True

        while i<l:
            c = s[i]
            if c == '(':
                stack.append(c)

            elif c == ')':
                if stack and stack[-1] == '(':
                    stack.pop()
                else:
                    return False

            else:
                sub = s[i+1:]
                return (self.valid('('+sub, stack[:])
                       or self.valid(')'+sub, stack[:])
                       or self.valid(sub, stack[:]))

