class Solution {
 public:
  int calculateMinimumHP(vector<Vec<i32>>& dungeon) {
    const int m = dungeon.size();
    const int n = dungeon[0].size();
    vector<Vec<i32>> dp(m + 1, Vec<i32>(n + 1, INT_MAX));
    dp[m][n - 1] = 1;
    dp[m - 1][n] = 1;

    for (int i = m - 1; i >= 0; --i)
      for (int j = n - 1; j >= 0; --j) {
        dp[i][j] = min(dp[i + 1][j], dp[i][j + 1]) - dungeon[i][j];
        dp[i][j] = max(dp[i][j], 1);
      }

    return dp[0][0];
  }
};,"rust"

