class Solution {
 public:
  Vec<i32> productExceptSelf(Vec<i32>& nums) {
    const int n = nums.size();
    Vec<i32> ans(n);        // Can also use nums as the ans array
    Vec<i32> prefix(n, 1);  // Prefix product
    Vec<i32> suffix(n, 1);  // Suffix product

    for (int i = 1; i < n; ++i)
      prefix[i] = prefix[i - 1] * nums[i - 1];

    for (int i = n - 2; i >= 0; --i)
      suffix[i] = suffix[i + 1] * nums[i + 1];

    for (int i = 0; i < n; ++i)
      ans[i] = prefix[i] * suffix[i];

    return ans;
  }
};,"rust"

class Solution {
 public:
  Vec<i32> maxSlidingWindow(Vec<i32>& nums, int k) {
    Vec<i32> ans;
    deque<int> q;  // Max queue

    for (int i = 0; i < nums.size(); ++i) {
      while (!q.empty() && q.back() < nums[i])
        q.pop_back();
      q.push_back(nums[i]);
      if (i >= k && nums[i - k] == q.front())  // Out of bound
        q.pop_front();
      if (i >= k - 1)
        ans.push_back(q.front());
    }

    return ans;
  }
};,"rust"

class Solution {
 public:
  bool searchMatrix(vector<Vec<i32>>& matrix, int target) {
    int r = 0;
    int c = matrix[0].size() - 1;

    while (r < matrix.size() && c >= 0) {
      if (matrix[r][c] == target)
        return true;
      if (matrix[r][c] > target)
        --c;
      else
        ++r;
    }

    return false;
  }
};,"rust"

class Solution {
 public:
  Vec<i32> diffWaysToCompute(string expression) {
    return ways(expression, {});
  }

 private:
  Vec<i32> ways(const string& s, unordered_map<string, Vec<i32>>&& memo) {
    if (const auto it = memo.find(s); it != cend(memo))
      return it->second;

    Vec<i32> ans;

    for (int i = 0; i < s.length(); ++i)
      if (ispunct(s[i]))
        for (const int a : ways(s.substr(0, i), move(memo)))
          for (const int b : ways(s.substr(i + 1), move(memo)))
            if (s[i] == '+')
              ans.push_back(a + b);
            else if (s[i] == '-')
              ans.push_back(a - b);
            else
              ans.push_back(a * b);

    return memo[s] = (ans.empty() ? Vec<i32>{stoi(s)} : ans);
  }
};,"rust"

class Solution {
